import {mountGooglePanel} from './google-panel.mjs';
import {importRouteAutomatically,cancelRouteImport} from './route-client.mjs';
import {routesToKML} from './route-import.mjs';
import {defaults,valid,max,q,worst,distance,sample,validate,hours,assess,totals,forecast,getJSON,parseCSV,cell,review,geo,rainSpread} from './core.mjs';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s=structuredClone(defaults),snap=null,history=[],active='home',activity='asphalt',busy=false,candidate=null,key='',routeInputs=null, importedLines=[], importedIndex=0, importSerial=0, importSummary=null, importPage=0, importAxes=[], importHidden=[], showAnnotations=false;
let db=await new Promise((resolve,reject)=>{let r=indexedDB.open('yuan-weather',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}).catch(()=>null);
const read=k=>db?new Promise(resolve=>{let r=db.transaction('data').objectStore('data').get(k);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null)}):Promise.resolve(null);
const write=(k,v)=>db?new Promise((resolve,reject)=>{let t=db.transaction('data','readwrite');t.objectStore('data').put(v,k);t.oncomplete=resolve;t.onerror=()=>reject(t.error)}):Promise.reject(Error('Storage unavailable / 本地存储不可用'));
try{s={...s,...await read('settings')};validate(s);snap=await read('snapshot');history=await read('history')||[]}catch(e){s=structuredClone(defaults);$('status').textContent=e.message}
const T=(zh,fr)=>s.lang==='fr'?fr:zh,N=(v,d=1)=>valid(v)?v.toLocaleString(s.lang==='fr'?'fr-FR':'zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const time=(t,date=false)=>new Intl.DateTimeFormat(s.lang==='fr'?'fr-FR':'zh-CN',{timeZone:s.zone,month:'2-digit',day:'2-digit',...(date?{}:{hour:'2-digit',minute:'2-digit',hourCycle:'h23'})}).format(new Date(t*1000));
const day=t=>new Intl.DateTimeFormat('sv-SE',{timeZone:s.zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t*1000));
const acts=()=>({rain:T('降雨风险','Pluie'),earth:T('土方 / 压实','Terrassement'),asphalt:T('沥青摊铺','Enrobés'),concrete:T('混凝土浇筑','Bétonnage'),lifting:T('吊装 / 高处','Levage / hauteur'),emulsion:T('乳化沥青','Émulsion')});
const kinds=()=>({route:T('沿线点','Route'),bridge:T('桥位','Pont'),culvert:T('涵洞','Dalot'),low:T('低洼段','Zone basse'),depot:T('料场','Dépôt'),plant:T('拌合站','Centrale')});
const levels=()=>[T('灰色 · 待核实','Gris · à vérifier'),T('绿色 · 条件满足','Vert · critères satisfaits'),T('黄色 · 先备防雨','Jaune · protéger'),T('红色 · 暂停工序','Rouge · suspendre')];
const reason=k=>({thunder:T('GFS雷暴代码','Code orage GFS'),wind:T('风速／阵风超过阈值','Vent / rafales au-dessus du seuil'),rainRed:T('降雨触发红色阈值','Seuil rouge de pluie'),rainYellow:T('降雨触发黄色阈值','Seuil jaune de pluie'),cape:T('CAPE偏高，需核实雷暴','CAPE élevé : risque à vérifier'),wet:T('前24小时模型雨量偏多，复工前实测含水量','Pluie modélisée sur 24 h élevée : mesurer l’humidité'),cold:T('气温低于沥青阈值（按CCTP调整）','Température sous le seuil des enrobés (CCTP)'),hot:T('环境气温偏高，另测混凝土入模温度','Air chaud : mesurer la température du béton'),stale:T('预报已超过12小时','Prévision de plus de 12 h'),missing:T('关键数据不足，不能判为可施工','Données clés manquantes'),ok:T('所设天气条件满足，仍需现场确认','Critères météo satisfaits, à confirmer sur chantier')})[k];
function status(text){$('status').textContent=text||''}
function bind(id,fn){if($(id))$(id).onclick=async()=>{try{await fn()}catch(e){status(e.message)}}}
const field=(id,label,value,type='number',extra='')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${extra}>`;
function relevant(p){return snap?.model===s.model&&snap?.commercial===s.commercial?snap.forecasts.find(f=>f.id===p.id):null}
function rowsFor(p){let f=relevant(p);return hours(f||{},Date.now())}
function state(h,p){let f=relevant(p);return assess(h,s,p,activity,!f||Date.now()-f.fetched>12*3600000)}
function notes(){return T('已接入 AIFS、WeatherNext 2、IFS、ICON；GFS提供辅助场。雨量按各确定性模型与WN P90中较大值判级，风取较大值；降雨概率仍仅来自WN集合。5 km是取点间距，不是模型分辨率。AIFS / WeatherNext 2原始时步较粗，逐小时值由服务商插值。P90不是最大值；概率为有效集合成员中雨量>0.2 mm的比例。前24h雨量来自模型，不是现场实测。灰色或过期不能认定可施工。阈值按CCTP调整。','Modèles : AIFS, WeatherNext 2, IFS, ICON ; GFS en complément. Risque pluie : maximum des modèles déterministes et du P90 WN ; vent maximal. Probabilité issue uniquement de WN. 5 km est l’espacement des points, pas la résolution du modèle. AIFS / WeatherNext 2 sont interpolés à l’heure par le fournisseur. P90 n’est pas un maximum ; probabilité = proportion des membres valides > 0,2 mm. La pluie sur 24 h est modélisée, non observée. Gris ou périmé : aptitude non confirmée. Adapter les seuils au CCTP.')}
function render(){document.documentElement.lang=s.lang;$('language').textContent=s.lang==='zh'?'FR':'中文';document.querySelector('h1').textContent=T('源的天气','Météo de Yuan');$('nav').innerHTML=Object.entries({home:T('施工看板','Chantier'),route:T('路线与监测点','Itinéraire'),settings:T('设置','Réglages'),review:T('每周复盘','Bilan')}).map(([id,title])=>`<button data-tab="${id}" class="${active===id?'active':''}">${title}</button>`).join('');$('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{active=b.dataset.tab;render();window.scrollTo(0,0)});for(let id of ['home','route','settings','review'])$(id).hidden=id!==active;$('foot').innerHTML=`${esc(notes())}<br>© <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a> · ECMWF · DWD · Google DeepMind · NOAA GFS · © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> / OSRM`;if(active==='home')renderHome();if(active==='route')renderRoute();if(active==='settings')renderSettings();if(active==='review')renderReview()}
function renderHome(){let today=day(Date.now()/1000),summary=s.sites.map(p=>{let rows=rowsFor(p).filter(h=>day(h.t-1)>today).filter((h,i,a)=>day(h.t-1)===day(a[0].t-1)),red=rows.filter(h=>state(h,p).level===2);return red.length?`${p.pk} ${T('明日红色时段（小时结束时间）','Demain rouge (fin d’heure)')} ${red.map(h=>time(h.t).split(' ').at(-1)).join(' · ')}`:`${p.pk} ${levels()[worst(rows.map(h=>state(h,p).level))+1]}`});$('home').innerHTML=`<div class="card hero"><div class="eyebrow">${T('围绕每天能不能干活','PLANIFIER LES TRAVAUX')}</div><h2 style="margin-top:10px">${T('先看天气，再排工序','La météo avant le planning')}</h2><p class="note">ECMWF AIFS · WeatherNext 2 · ECMWF IFS · DWD ICON</p><p>${s.sites.length} ${T('个监测点','points')} · 72 h / 7 ${T('天','jours')}</p><div class="toolbar spread"><small>${snap?T('上次获取 ','Dernier relevé ')+time(snap.fetched/1000):T('尚未获取预报','Aucune prévision')}</small><button class="primary" id="refresh" ${busy?'disabled':''}>${busy?T('正在获取…','Chargement…'):T('刷新预报','Actualiser')}</button></div></div>${!s.sites.length?`<div class="card"><h2>${T('先输入路段GPS起终点','Saisir les coordonnées GPS')}</h2><p>${T('沿实际道路每5公里自动取点。','Un point tous les 5 km le long de la route.')}</p><button id="goRoute">${T('设置路线','Configurer')}</button></div>`:''}<div class="card"><div class="toolbar spread"><h2>${T('72小时施工颜色表','Travaux · 72 heures')}</h2><select id="activity" style="width:auto;max-width:100%">${Object.entries(acts()).map(([k,v])=>`<option value="${k}" ${k===activity?'selected':''}>${v}</option>`).join('')}</select></div><div class="chips">${[-1,0,1,2].map(l=>`<span class="badge risk${l}">${levels()[l+1]}</span>`).join('')}</div><p class="muted">${T('左右滑动；点格子看依据。时间为该小时结束时间。','Faire défiler ; toucher une case pour les détails. Heure de fin de période.')} · ${s.zone}</p><div class="scroll">${heatTable()}</div></div><div class="card"><h2>${T('明日安排提示','Repères pour demain')}</h2><pre>${esc(summary.join('\n')||T('配置路线并刷新后显示。','Configurer puis actualiser.'))}</pre><p class="note">${T('红色时段避开所选工序；黄色先备防雨、不新开作业面。未显示红色不等于全天可以施工。','Éviter le travail sélectionné pendant les heures rouges. Jaune : protéger, pas de nouveau front. L’absence de rouge ne garantit pas une journée praticable.')}</p></div><div class="card"><h2>${T('未来7天 · 当地日历日','7 jours · calendrier local')}</h2><p class="muted">${T('今天仅包含余下时段；雨量按成员先累计后取P50/P90。','Aujourd’hui : heures restantes. Cumul par membre avant P50/P90.')}</p><div class="scroll">${dailyTable()}</div><div class="toolbar" style="margin-top:14px"><button id="exportCsv">CSV</button><button id="exportHtml">${T('导出报告','Rapport HTML')}</button></div></div><div class="card install"><h3>${T('iPhone添加到主屏幕','Ajouter sur iPhone')}</h3><p>${T('用Safari打开此网页 → 分享 → 添加到主屏幕。首次联网打开后可离线查看上次预报。','Ouvrir dans Safari → Partager → Sur l’écran d’accueil. Après la première ouverture en ligne, la dernière prévision reste consultable hors connexion.')}</p><p class="note">${T('不推送。手机关闭应用时不保证06:00／14:00执行；打开或回到应用后补刷新。','Sans notifications. Exécution à 06 h / 14 h non garantie lorsque l’application est fermée ; rattrapage à la réouverture.')}</p></div>`;bind('refresh',refresh);bind('goRoute',()=>{active='route';render()});$('activity').onchange=e=>{activity=e.target.value;renderHome()};bind('exportCsv',exportCsv);bind('exportHtml',exportHtml);$('home').querySelectorAll('[data-hour]').forEach(b=>b.onclick=()=>showHour(b.dataset.point,Number(b.dataset.hour)));mountGooglePanel($('home'),{s,T,esc,time,N})}
function heatTable(){let template=hours({},Date.now(),72);return `<table><thead><tr><th>PK</th>${template.map(h=>`<th>${time(h.t)}</th>`).join('')}</tr></thead><tbody>${s.sites.map(p=>`<tr><td>${esc(p.pk)}<br><small>${esc(p.name)}</small></td>${rowsFor(p).slice(0,72).map((h,i)=>{let a=state(h,p);return `<td><button class="risk${a.level}" data-point="${p.id}" data-hour="${i}" aria-label="${esc(p.pk+' '+time(h.t)+' '+levels()[a.level+1])}">${N(max([h.a,h.p90]))}</button></td>`}).join('')}</tr>`).join('')}</tbody></table>`}
function dailyTable(){let start=day(Date.now()/1000),days=Array.from({length:7},(_,i)=>new Date(Date.parse(start+'T12:00:00Z')+i*86400000).toISOString().slice(0,10));return `<table><thead><tr><th>PK</th>${days.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${s.sites.map(p=>{let rows=rowsFor(p),f=relevant(p);return `<tr><td>${esc(p.pk)}</td>${days.map(d=>{let r=rows.filter(h=>day(h.t-1)===d),t=totals(f||{},r),l=worst(r.map(h=>state(h,p).level));return `<td class="risk${l}" style="padding:10px;border-radius:8px">${levels()[l+1]}<br>AIFS ${N(t.a)} mm<br>IFS ${N(t.ifs)} mm · ICON ${N(t.icon)} mm<br>P50 / P90 ${N(t.p50)} / ${N(t.p90)} mm<br>${T('最高气温','T° max')} ${N(max(r.flatMap(h=>[h.at,h.gt,h.it,h.dt])))} °C</td>`}).join('')}</tr>`}).join('')}</tbody></table>`}
function showHour(id,i){let p=s.sites.find(x=>x.id===id),h=rowsFor(p)[i],a=state(h,p);$('detailBody').innerHTML=`<h2>${esc(p.pk)} · ${time(h.t)}</h2><span class="badge risk${a.level}">${levels()[a.level+1]}</span><p>${a.reasons.map(reason).join('<br>')}</p><dl>${[[T('IFS雨量','Pluie IFS'),N(h.ifs)+' mm'],[T('ICON雨量','Pluie ICON'),N(h.icon)+' mm'],[T('模型雨量分歧（最大−最小，含WN P50）','Écart pluie (max−min, avec P50 WN)'),N(rainSpread(h))+' mm/h'],['IFS / ICON °C',N(h.it)+' / '+N(h.dt)],['IFS / ICON m/s',N(h.iw)+' / '+N(h.dw)],[T('AIFS雨量','Pluie AIFS'),N(h.a)+' mm'],['WeatherNext P50 / P90',`${N(h.p50)} / ${N(h.p90)} mm`],[T('集合降雨概率','Probabilité ensemble'),N(h.prob)+' %'],[T('有效成员','Membres valides'),h.n+'/'+h.expected],[T('前24h模型雨量','Pluie modélisée 24 h'),N(h.wet)+' mm'],['AIFS / WeatherNext °C',N(h.at)+' / '+N(h.gt)],[T('风速 / 阵风','Vent / rafales'),N(h.wind)+' / '+N(h.gust)+' m/s'],['CAPE',N(h.cape,0)+' J/kg'],[T('天气代码','Code météo'),N(h.code,0)]].map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><p class="note">${notes()}</p>`;$('detail').showModal()}
$('closeDetail').onclick=()=>$('detail').close();
async function refresh(){if(busy)return;if(!navigator.onLine)throw Error(T('当前离线，保留上次预报。','Hors connexion : dernière prévision conservée.'));if(!s.sites.length){active='route';render();return}if(s.commercial&&!key){active='settings';render();status(T('请输入商业API密钥；仅本次会话使用。','Saisir la clé commerciale (session uniquement).'));return}busy=true;render();let all=[],configuration=JSON.stringify(s);try{for(let i=0;i<s.sites.length;i++){status(`${T('正在获取','Chargement')} ${i+1}/${s.sites.length} · ${s.sites[i].pk}`);all.push(await forecast(s.sites[i],s,key));await new Promise(r=>setTimeout(r,250))}if(JSON.stringify(s)!==configuration)throw Error(T('配置已改变，请重新刷新','Configuration modifiée : actualiser à nouveau'));if(all.every(f=>!f.a&&!f.g&&!f.s&&!f.i&&!f.d))throw Error(T('所有接口均失败，保留上次预报。','Tous les services ont échoué ; dernière prévision conservée.'));snap={fetched:Date.now(),model:s.model,commercial:s.commercial,forecasts:all};await write('snapshot',snap);history.push({fetched:snap.fetched,rows:all.flatMap(f=>hours(f,snap.fetched,192).map(h=>({id:f.id,t:h.t,p50:h.p50,p90:h.p90,a:h.a,ifs:h.ifs,icon:h.icon})))});history=history.filter(b=>b.fetched>Date.now()-10*86400000);await write('history',history);let errors=all.flatMap(f=>f.errors.map(e=>`${s.sites.find(p=>p.id===f.id)?.pk}: ${e}`));status(errors.length?T('部分数据不可用，已标灰：\n','Données partielles, gris :\n')+errors.join('\n'):T('预报已更新并保存在本机。','Prévisions actualisées et enregistrées sur cet appareil.'))}finally{busy=false;render()}}
function routeSVG(path,points){if(!path?.length)return '';let lat=path.map(x=>x[0]),lon=path.map(x=>x[1]),minX=Math.min(...lon),maxX=Math.max(...lon),minY=Math.min(...lat),maxY=Math.max(...lat),scale=Math.min(560/(maxX-minX||.01),200/(maxY-minY||.01));let xy=([a,b])=>[20+(b-minX)*scale,220-(a-minY)*scale];return `<svg viewBox="0 0 600 240" aria-label="${T('路线示意','Schéma du tracé')}"><polyline points="${path.map(x=>xy(x).join(',')).join(' ')}" fill="none" stroke="#326b51" stroke-width="3"/>${points.map(p=>{let[x,y]=xy([p.lat,p.lon]);return `<circle cx="${x}" cy="${y}" r="4" fill="#dc7d34"/><text x="${x+5}" y="${y-5}" font-size="9">${esc(p.pk)}</text>`}).join('')}</svg>`}
function renderRoute(){let input=routeInputs||['','','','','0'];$('route').innerHTML=`<div class="card"><h2>${T('GPS起终点 → 沿路布点','GPS → points le long de la route')}</h2><p class="note">${T('输入WGS84十进制度。查询实际道路，预览后确认；不以直线代替道路。道路与设计线不符时导入 KMZ / KML / CSV。','Coordonnées WGS84 décimales. Vérifier le tracé routier avant confirmation. Importer le tracé projet en KMZ / KML / CSV si nécessaire ; pas de remplacement par une ligne droite.')}</p><div class="grid">${field('startLat',T('起点纬度','Latitude départ'),input[0])}${field('startLon',T('起点经度','Longitude départ'),input[1])}${field('endLat',T('终点纬度','Latitude arrivée'),input[2])}${field('endLon',T('终点经度','Longitude arrivée'),input[3])}</div>${field('origin',T('起点桩号（米，K12+500填12500）','PK initial en mètres (K12+500 = 12500)'),input[4])}<div class="toolbar" style="margin-top:15px"><button class="primary" id="findRoute" ${busy?'disabled':''}>${T('查询道路','Chercher la route')}</button><button id="importRoute" ${busy?'disabled':''}>${T('导入 KMZ / KML / CSV','Importer KMZ / KML / CSV')}</button><button id="routeTemplate">${T('CSV模板','Modèle CSV')}</button></div><input id="routeFile" type="file" accept=".kmz,.kml,.csv,application/vnd.google-earth.kmz,application/vnd.google-earth.kml+xml,text/csv" hidden><div id="importedLineChoice"></div><div id="routePreview"></div></div><div class="card"><h2>${T('当前监测点','Points actuels')}</h2>${routeSVG(s.route,s.sites)}<div class="points">${s.sites.map(p=>`<div class="point"><span><b>${esc(p.pk)}</b> · ${esc(p.name)} · ${kinds()[p.kind]||''}<br><small>${p.lat.toFixed(5)}, ${p.lon.toFixed(5)}${p.rainRed?` · R≥${p.rainRed}`:''}${p.wet24?` · 24h≥${p.wet24}`:''}</small></span><button data-delete="${p.id}" ${busy?'disabled':''}>${T('删除','Retirer')}</button></div>`).join('')}</div></div><div class="card"><h2>${T('补充重点监测点','Ajouter un point sensible')}</h2><div class="grid">${field('pointPK','PK (K12+500)','','text')}${field('pointName',T('名称','Nom'),'','text')}${field('pointLat',T('纬度','Latitude'),'')}${field('pointLon',T('经度','Longitude'),'')}</div><label>${T('类型','Type')}</label><select id="pointKind">${Object.entries(kinds()).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><div class="grid">${field('pointRed',T('本点红色雨量 mm/h（可空）','Seuil rouge local mm/h (facultatif)'),'')}${field('pointWet',T('本点24h雨量阈值 mm（可空）','Seuil local 24 h mm (facultatif)'),'')}</div><button id="addPoint" class="primary" style="margin-top:15px" ${busy?'disabled':''}>${T('添加 / 更新相同桩号','Ajouter / modifier le même PK')}</button></div>`;for(let id of ['startLat','startLon','endLat','endLon','origin'])$(id).oninput=()=>{if(id==='origin'&&importedLines.length){selectImportedLine();return}importSerial++;cancelRouteImport();importedLines=[];candidate=null;$('importedLineChoice').innerHTML='';$('routePreview').innerHTML='';routeInputs=['startLat','startLon','endLat','endLon','origin'].map(id=>$(id).value)};bind('findRoute',findRoute);bind('routeTemplate',()=>download('design-route.csv','latitude,longitude\n7.25,2.3333\n7.17,2.07\n','text/csv'));bind('importRoute',()=>$('routeFile').click());$('routeFile').onchange=loadRouteFile;bind('addPoint',addPoint);$('route').querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(busy)return;if(!confirm(T('删除该监测点？','Retirer ce point ?')))return;s.sites=s.sites.filter(p=>p.id!==b.dataset.delete);await write('settings',s);renderRoute()});renderImportedChoice();previewRoute()}

async function loadRouteFile(e){const file=e.target.files?.[0];if(!file)return;const serial=++importSerial;candidate=null;importedLines=[];$('routePreview').innerHTML='';$('importedLineChoice').innerHTML='';status(T('正在自动提取和整理线路…','Extraction et préparation automatiques…'));try{const prepared=await importRouteAutomatically(file,p=>{if(serial===importSerial)status(p.stage==='merge'?T('正在连接碎线并按长度排序…','Jonction et classement des tracés…'):T('正在读取线路，自动跳过媒体…','Lecture des tracés, médias ignorés…'))});const result=prepared.routes;if(serial!==importSerial)return;importAxes=result;importHidden=prepared.hiddenRoutes||[];showAnnotations=false;importedLines=importAxes;importedIndex=0;importPage=0;importSummary=prepared.summary;status(importSummary?T('自动整理完成：'+importSummary.segments+' 个线段 → '+importSummary.routes+' 条道路候选，已隐藏 '+(importSummary.hidden||0)+' 条疑似标注；请核对方向。','Préparation terminée : '+importSummary.segments+' segments → '+importSummary.routes+' tracés, '+(importSummary.hidden||0)+' annotations probables masquées ; vérifier le sens.'): /\.kmz$/i.test(file.name)?T('已自动提取 KML 线路，跳过图片和视频；请选择线路并确认方向。','KML extrait automatiquement, images et vidéos ignorées ; vérifier le tracé.'):T('文件已在本机读取；请选择线路并确认方向。','Fichier lu localement ; choisir le tracé et vérifier son sens.'));renderImportedChoice();}catch(error){if(serial===importSerial)status(error.message)}finally{e.target.value=''}}
function renderImportedChoice(){if(!$('importedLineChoice'))return;if(!importedLines.length){$('importedLineChoice').innerHTML='';return}$('importedLineChoice').innerHTML=`${importHidden.length?`<div class="note">${T('已自动隐藏 '+importHidden.length+' 条疑似文字、桩号标注碎线。识别依据为成组短线特征，可随时查看并恢复选择。',importHidden.length+' annotations probables masquées selon les groupes de petits tracés. Vous pouvez les afficher et les sélectionner.')}</div><label><input type="checkbox" id="showAnnotations" ${showAnnotations?'checked':''}> ${T('查看被隐藏线段','Afficher les tracés masqués')}</label>`:''}<button id="saveCleanKML">${T('保存纯线路 KML（不含图片视频）','Enregistrer le KML sans images ni vidéos')}</button><p class="note">${importedLines.length>256?T('已自动整理 '+importedLines.length+' 条候选线路，按长度排序；每页256条，可翻页查看全部。仅连接同组端点重合且无分叉的碎线。',''+importedLines.length+' tracés classés par longueur, 256 par page. Jonction aux extrémités identiques, sans bifurcation.') : ''}</p><button id="saveSelectedKML">${T('保存当前选中线路 KML','Enregistrer le tracé sélectionné en KML')}</button><label for="importedLineSelect">${T('选择文件中的线路','Choisir le tracé dans le fichier')} (${importedLines.length})</label><select id="importedLineSelect">${importedLines.slice(importPage*256,(importPage+1)*256).map((r,j)=>{let i=importPage*256+j;return `<option value="${i}" ${i===importedIndex?'selected':''}>${r.annotationReason?T('[疑似标注] ','[Annotation probable] '):''}${esc(r.name)} · ${N(r.length/1000)} km · ${esc(r.source)}</option>`}).join('')}</select><div class="toolbar"><button id="importPrev" ${importPage===0?'disabled':''}>${T('上一页','Précédent')}</button><span>${importPage+1} / ${Math.ceil(importedLines.length/256)}</span><button id="importNext" ${(importPage+1)*256>=importedLines.length?'disabled':''}>${T('下一页','Suivant')}</button></div><label><input type="checkbox" id="reverseImportedLine"> ${T('反转线路方向（交换起终点）','Inverser le sens du tracé')}</label><p class="note">${T('使用文件中的线路几何，每5公里布点；不重新规划道路。多条线路分开选择，不自动跨段连接。调整上方起点桩号后预览自动更新。','Géométrie du fichier, points tous les 5 km, sans recalcul routier. Tracés séparés, sans raccordement automatique. Modifier le PK initial ci-dessus pour actualiser.')}</p>`;if($('showAnnotations'))$('showAnnotations').onchange=e=>{showAnnotations=e.target.checked;importedLines=showAnnotations?[...importAxes,...importHidden]:importAxes;importPage=0;importedIndex=0;renderImportedChoice()};bind('importPrev',()=>{importPage--;importedIndex=importPage*256;renderImportedChoice()});bind('importNext',()=>{importPage++;importedIndex=importPage*256;renderImportedChoice()});bind('saveSelectedKML',()=>{let line=importedLines[importedIndex];if(line)download('selected-route.kml',routesToKML([{...line,path:$('reverseImportedLine').checked?line.path.slice().reverse():line.path}]),'application/vnd.google-earth.kml+xml')});bind('saveCleanKML',()=>download('route-lines.kml',routesToKML(importedLines),'application/vnd.google-earth.kml+xml'));$('importedLineSelect').onchange=e=>{importedIndex=Number(e.target.value);selectImportedLine()};$('reverseImportedLine').onchange=selectImportedLine;selectImportedLine()}
function selectImportedLine(){try{let line=importedLines[importedIndex];if(!line)return;let raw=$('origin').value;if(!raw.trim())throw Error(T('请输入起点桩号米数','Saisir le PK initial en mètres'));let path=$('reverseImportedLine')?.checked?[...line.path].reverse():line.path;candidate={path,source:line.name,...sample(path,Number(raw))};routeInputs=['startLat','startLon','endLat','endLon','origin'].map(id=>$(id).value);previewRoute()}catch(e){candidate=null;$('routePreview').innerHTML='';status(e.message)}}

async function findRoute(){importSerial++;cancelRouteImport();importedLines=[];$('importedLineChoice').innerHTML='';let vals=['startLat','startLon','endLat','endLon'].map(id=>$(id).value);if(vals.some(x=>!x.trim()))throw Error(T('请输入四个GPS坐标','Saisir les quatre coordonnées'));let requestInputs=JSON.stringify([...vals,$('origin').value]);let[a,b,c,d]=vals.map(Number);if(!geo([a,b])||!geo([c,d]))throw Error('GPS');$('findRoute').disabled=true;status(T('正在查询道路…','Recherche de l’itinéraire…'));try{let data=await getJSON(`https://routing.openstreetmap.de/routed-car/route/v1/driving/${b},${a};${d},${c}?overview=full&geometries=geojson&steps=false&radiuses=1000;1000`);if(data.code!=='Ok'||!data.routes?.length)throw Error(T('未找到道路；请导入设计线。','Aucun tracé ; importer le tracé projet.'));if(requestInputs!==JSON.stringify(['startLat','startLon','endLat','endLon','origin'].map(id=>$(id)?.value)))throw Error(T('输入已改变，请重新查询','Coordonnées modifiées : relancer'));let path=data.routes[0].geometry.coordinates.map(([lon,lat])=>[lat,lon]);candidate={path,...sample(path,Number($('origin').value)),snap:data.waypoints?.map(x=>x.distance)};previewRoute();status('')}catch(e){candidate=null;status(T('道路查询失败，未生成直线替代。可导入 KMZ / KML / CSV。 ','Échec du routage, aucun tracé droit substitué. Import CSV possible. ')+e.message)}finally{$('findRoute').disabled=false}}
function previewRoute(){if(!candidate||!$('routePreview'))return;$('routePreview').innerHTML=`<h3>${T('待确认路线','Tracé à confirmer')} · ${N(candidate.length/1000)} km · ${candidate.sites.length} ${T('个点','points')}</h3>${routeSVG(candidate.path,candidate.sites)}<p class="note">${T('示意图无底图。请核对道路走向；确认后替换沿线点，保留桥涵等额外点。','Schéma sans fond cartographique. Vérifier le tracé ; confirmation remplace les points routiers et conserve les points sensibles.')} ${candidate.source?esc(candidate.source)+' · ':''}${candidate.snap?T('GPS吸附距离 ','Distance de recalage ')+candidate.snap.map(x=>N(x,0)+' m').join(' / '):''}</p><button class="primary" id="applyRoute">${T('确认使用这条路线','Confirmer ce tracé')}</button>`;bind('applyRoute',async()=>{if(busy)return;let next={...s,route:candidate.path,sites:[...candidate.sites,...s.sites.filter(p=>p.kind!=='route')]};validate(next);s=next;await write('settings',s);candidate=null;importedLines=[];status(T('路线已保存，点击刷新获取预报。','Tracé enregistré. Actualiser pour charger la météo.'));renderRoute()})}
async function addPoint(){if(busy)return;let inputs=['pointPK','pointLat','pointLon'].map(id=>$(id).value.trim());if(inputs.some(v=>!v))throw Error(T('桩号和坐标必填','PK et coordonnées obligatoires'));let p={id:crypto.randomUUID(),pk:inputs[0],name:$('pointName').value,kind:$('pointKind').value,lat:Number(inputs[1]),lon:Number(inputs[2]),rainRed:$('pointRed').value?Number($('pointRed').value):null,wet24:$('pointWet').value?Number($('pointWet').value):null};let old=s.sites.find(x=>x.pk===p.pk);if(old){if(!confirm(T('更新这个桩号的监测点？','Modifier le point de ce PK ?')))return;if(old.lat===p.lat&&old.lon===p.lon)p.id=old.id}let next={...s,sites:[...s.sites.filter(x=>x.pk!==p.pk),p]};validate(next);s=next;await write('settings',s);renderRoute()}
const thresholdLabels=()=>({rainYellow:T('黄色雨量 mm/h','Pluie jaune mm/h'),rainRed:T('红色雨量 mm/h (≥)','Pluie rouge mm/h (≥)'),probYellow:T('黄色概率 % (≥)','Probabilité jaune % (≥)'),probRed:T('红色概率 % (>)','Probabilité rouge % (>)'),wet24:T('前24h雨量 mm','Pluie antérieure 24 h mm'),asphalt:T('沥青最低温 °C','T° minimale enrobés °C'),concrete:T('混凝土环境温提示 °C','Alerte température ambiante béton °C'),wind:T('停工风速 m/s (>)','Arrêt vent m/s (>)'),cape:T('CAPE提示 J/kg','Alerte CAPE J/kg')});
function renderSettings(){$('settings').innerHTML=`<div class="card"><h2>${T('工序阈值 · 按CCTP调整','Seuils de travaux · selon CCTP')}</h2><div class="grid">${Object.entries(thresholdLabels()).map(([k,v])=>field(k,v,s[k])).join('')}</div><p class="note">${T('默认雨量达到5 mm/h即红色；概率60%属于黄色，大于60%为红色。混凝土25°C是环境温提示，不能代替入模温度测量。','Par défaut, 5 mm/h est rouge. Probabilité 60 % : jaune ; > 60 % : rouge. Les 25 °C concernent l’air, pas la température mesurée du béton.')}</p><label>${T('项目时区','Fuseau du chantier')}</label><select id="zone">${['Africa/Porto-Novo','UTC','Asia/Shanghai'].map(z=>`<option ${z===s.zone?'selected':''}>${z}</option>`).join('')}</select><label><input type="checkbox" id="scheduled" ${s.scheduled?'checked':''}> ${T('06:00 / 14:00刷新（仅应用打开时；重新打开补刷新）','Actualiser à 06 h / 14 h si ouvert ; rattraper à la réouverture')}</label><details><summary>${T('模型与API设置','Modèle et API')}</summary><p>ECMWF IFS · DWD ICON · ECMWF AIFS · WeatherNext 2 · GFS</p>${field('model',T('Google模型标识','Identifiant du modèle Google'),s.model,'text')}<label><input type="checkbox" id="commercial" ${s.commercial?'checked':''}> ${T('Open-Meteo商业端点','Service commercial Open-Meteo')}</label>${field('apiKey',T('商业API密钥（仅本次会话，不保存）','Clé API commerciale (session uniquement)'),key,'password','autocomplete="off"')}<p class="note">${T('施工商业使用请按Open-Meteo订阅授权配置。免费端点用于符合其条款的非商业试用。Open-Meteo的WeatherNext 3标识尚未验证；Google付费入口位于施工看板底部。','Pour un usage commercial, configurer un abonnement Open-Meteo adapté. Le service gratuit est réservé aux usages non commerciaux autorisés. Identifiant WeatherNext 3 non validé chez Open-Meteo ; accès Google payant au bas du tableau de chantier.')}</p><a href="https://open-meteo.com/en/pricing" target="_blank" rel="noopener">Open-Meteo · ${T('订阅与条款','Abonnements')}</a></details><button class="primary" id="saveSettings" style="margin-top:18px" ${busy?'disabled':''}>${T('保存设置','Enregistrer')}</button></div><div class="card"><h2>${T('本机数据与备份','Données locales et sauvegarde')}</h2><p>${T('路线、预报、复盘历史保存在当前设备，不自动跨手机同步。浏览器清理数据会删除本机记录；建议定期备份。精简复盘记录保留10天。','Tracé, prévisions et historique restent sur cet appareil, sans synchronisation automatique. Un nettoyage du navigateur les supprime : sauvegarder régulièrement. Historique compact conservé 10 jours.')}</p><div class="toolbar"><button id="backup">${T('导出备份','Sauvegarder')}</button><button id="restore" ${busy?'disabled':''}>${T('恢复备份','Restaurer')}</button></div><input id="backupFile" type="file" accept=".json,application/json" hidden></div>`;bind('saveSettings',async()=>{let next=structuredClone(s);for(let k of Object.keys(thresholdLabels())){if(!$(k).value.trim())throw Error(T('阈值不能为空','Seuil obligatoire'));next[k]=Number($(k).value)}next.zone=$('zone').value;next.scheduled=$('scheduled').checked;next.model=$('model').value.trim();next.commercial=$('commercial').checked;validate(next);s=next;key=$('apiKey').value.trim();await write('settings',s);status(T('设置已保存。','Réglages enregistrés.'));render()});bind('backup',()=>download('YuanWeather-backup.json',JSON.stringify({version:1,settings:s,snapshot:snap,history}),'application/json'));bind('restore',()=>$('backupFile').click());$('backupFile').onchange=async e=>{try{if(busy)return;let file=e.target.files[0];if(file.size>100*1024*1024)throw Error('100 MB max');let data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.history)||!data.settings)throw Error('Invalid backup');validate(data.settings);if(!confirm(T('以备份替换本机配置和预报？','Remplacer les données locales par cette sauvegarde ?')))return;s=data.settings;snap=data.snapshot;history=data.history;await write('settings',s);await write('snapshot',snap);await write('history',history);status(T('备份已恢复。','Sauvegarde restaurée.'));render()}catch(e){status(e.message)}}}
function renderReview(){$('review').innerHTML=`<div class="card"><div class="eyebrow">${T('预报与实测','PRÉVISION ET OBSERVATION')}</div><h2 style="margin-top:10px">${T('每周复盘','Bilan hebdomadaire')}</h2><p>${T('导入最近7天逐小时实测降雨。匹配提前6–30小时发布、最接近提前24小时的WeatherNext P50预报；没有匹配历史就不生成准确率。','Importer la pluie horaire observée des 7 derniers jours. Comparaison avec WeatherNext P50 émis 6–30 h avant, au plus près de 24 h. Sans historique correspondant, aucun score inventé.')}</p><p class="note">${T('列：chainage,hour_end,rain_mm。时间填项目时区，YYYY-MM-DD HH:00，表示小时结束时间。首次安装需要先积累预报历史。','Colonnes : chainage,hour_end,rain_mm. Heure locale du projet au format YYYY-MM-DD HH:00, fin de l’heure. Il faut accumuler des prévisions après installation.')}</p><div class="toolbar"><button id="observationTemplate">${T('下载模板','Modèle CSV')}</button><button class="primary" id="importObservation">${T('导入实测CSV','Importer les observations')}</button></div><input type="file" id="observationFile" accept=".csv,text/csv" hidden><div id="reviewResult"></div></div>`;bind('observationTemplate',()=>download('observations.csv','chainage,hour_end,rain_mm\n','text/csv'));bind('importObservation',()=>$('observationFile').click());$('observationFile').onchange=async e=>{try{let result=review(await e.target.files[0].text(),history,s),groups=[...new Set(result.map(r=>r.pk))];$('reviewResult').innerHTML=result.length?`<h3>${T('已匹配','Correspondances')} ${result.length}</h3><div class="scroll"><table><tr><th>PK</th><th>n</th><th>MAE mm</th><th>${T('偏差 mm','Biais mm')}</th></tr>${groups.map(pk=>{let rows=result.filter(r=>r.pk===pk);return `<tr><td>${esc(pk)}</td><td>${rows.length}</td><td>${N(rows.reduce((a,r)=>a+Math.abs(r.error),0)/rows.length,2)}</td><td>${N(rows.reduce((a,r)=>a+r.error,0)/rows.length,2)}</td></tr>`}).join('')}</table></div><p class="note">${T('偏差=预报−实测。结合现场条件调整单点降雨阈值；不自动修改安全或CCTP阈值。','Biais = prévision − observation. Ajuster les seuils locaux selon le terrain ; aucune modification automatique des seuils de sécurité / CCTP.')}</p><button id="exportReview">${T('导出匹配记录','Exporter les correspondances')}</button>`:`<p>${T('暂无匹配记录；请先积累预报，再导入对应时段实测。','Aucune correspondance ; accumuler les prévisions puis importer les observations correspondantes.')}</p>`;await write('lastReview',{date:Date.now(),result});bind('exportReview',()=>download('review.csv','chainage,hour_end,actual_mm,p50_mm,error_mm\n'+result.map(r=>[r.pk,time(r.t),r.actual,r.p50,r.error].map(cell).join(',')).join('\n'),'text/csv'))}catch(e){status(e.message)}}}
async function download(name,text,type){if(window.webkit?.messageHandlers?.save){window.webkit.messageHandlers.save.postMessage({name,text,type});return}if(window.YuanAndroid){window.YuanAndroid.save(name,text,type);return}let blob=new Blob(['\uFEFF'+text],{type}),file=new File([blob],name,{type});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file]});return}catch(e){if(e.name==='AbortError')return}}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function exportCsv(){let header=['PK',T('小时结束(项目时区)','Fin d’heure (fuseau projet)'),'AIFS mm','IFS mm','ICON mm',T('模型雨量分歧 mm/h','Écart pluie mm/h'),'P50 mm','P90 mm',T('概率 %','Probabilité %'),T('成员','Membres'),T('前24h模型 mm','Pluie modélisée 24 h mm'),'AIFS °C','WN °C','IFS °C','ICON °C','IFS m/s','ICON m/s',T('风 m/s','Vent m/s'),T('阵风 m/s','Rafales m/s'),'CAPE','code',...Object.values(acts())];let data=s.sites.flatMap(p=>rowsFor(p).slice(0,168).map(h=>[p.pk,time(h.t),h.a,h.ifs,h.icon,rainSpread(h),h.p50,h.p90,h.prob,h.n,h.wet,h.at,h.gt,h.it,h.dt,h.iw,h.dw,h.wind,h.gust,h.cape,h.code,...Object.keys(acts()).map(a=>levels()[assess(h,s,p,a,!relevant(p)||Date.now()-relevant(p).fetched>43200000).level+1])]));return download('YuanWeather-forecast.csv',[header,...data].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv')}
function exportHtml(){return download('YuanWeather-report.html',`<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>源的天气</title><style>body{font:14px sans-serif;padding:20px}table{border-collapse:collapse;white-space:nowrap}td,th{border:1px solid #ddd;padding:8px}.risk0{background:#c6e9ce}.risk1{background:#ffe3a0}.risk2{background:#f5b6ab}.risk-1{background:#dfe4e4}button{border:0;background:transparent;padding:5px}small{font-size:11px}.scroll{overflow:auto}</style><h1>源的天气 · Météo de Yuan</h1><p>${time(Date.now()/1000)} · ${esc(s.zone)} · ${acts()[activity]}</p><p>${levels().join(' / ')}</p><h2>72 h</h2><div class="scroll">${heatTable()}</div><h2>7 ${T('天','jours')}</h2><div class="scroll">${dailyTable()}</div><p>${esc(notes())}</p><p>Open-Meteo / ECMWF / DWD / Google DeepMind / NOAA</p>`,'text/html')}
$('language').onclick=async()=>{if(busy)return;s.lang=s.lang==='zh'?'fr':'zh';status('');await write('settings',s);render()};
let attemptedSlot='';async function autoRefresh(){if(!s.scheduled||busy||!s.sites.length||(document.hidden&&!window.YuanMac)||!navigator.onLine||s.commercial&&!key)return;let parts=new Intl.DateTimeFormat('en-GB',{timeZone:s.zone,hour:'2-digit',hourCycle:'h23'}).format(new Date()),hour=Number(parts),d=day(Date.now()/1000),slot=d+(hour>=14?'T14':hour>=6?'T06':'T00');if(hour<6)return;let offset=s.zone==='Asia/Shanghai'?'+08:00':s.zone==='UTC'?'Z':'+01:00',due=Date.parse(slot+':00:00'+offset);if((snap?.fetched||0)<due&&attemptedSlot!==slot){attemptedSlot=slot;try{await refresh()}catch(e){status(e.message)}}}
if(window.YuanMac){document.body.classList.add('mac')}render();if(!db)status(T('当前环境无法保存本机数据。','Stockage local indisponible.'));if('serviceWorker'in navigator&&!window.YuanAndroid&&!window.YuanMac)navigator.serviceWorker.register('./sw.js').catch(()=>status(T('离线缓存未启用，请保持联网。','Cache hors connexion indisponible ; rester connecté.')));setInterval(autoRefresh,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();autoRefresh()}});setTimeout(autoRefresh,1500);
